//! Replay del layout real: decodifica una cuenta de devnet con el struct compilado.
//! Si el struct y los bytes no coinciden, este test lo dice sin gastar lamports.

use anchor_lang::AccountDeserialize;
use the_pit::state::Arena;

const HEX: &str = "";

fn bytes() -> Vec<u8> {
    (0..HEX.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&HEX[i..i + 2], 16).unwrap())
        .collect()
}

#[test]
fn decodes_real_devnet_account() {
    let data = bytes();
    let mut slice: &[u8] = &data;
    let arena = Arena::try_deserialize(&mut slice).expect("deserialize");
    println!(
        "players={} max={} status={:?} rake={} duration={}",
        arena.player_count, arena.max_players, arena.status, arena.rake_bps, arena.duration
    );
    assert_eq!(arena.max_players, 8, "max_players mal leido");
    assert_eq!(arena.player_count, 0);
    assert_eq!(arena.duration, 300);
}

#[test]
fn account_wrapper_path_matches() {
    use anchor_lang::prelude::*;
    let data = bytes();
    let key = Pubkey::new_unique();
    let owner = the_pit::ID;
    let mut lamports = 1u64;
    let mut data_mut = data.clone();
    let info = AccountInfo::new(&key, false, true, &mut lamports, &mut data_mut, &owner, false);
    let acc = Account::<Arena>::try_from(&info).expect("try_from");
    println!(
        "try_from: players={} max={} status={:?}",
        acc.player_count, acc.max_players, acc.status
    );
    assert_eq!(acc.max_players, 8, "Account::try_from lee mal");
}
